class AESCipher:
    def __init__(self, key):
        self.key = key
        self.cipher = AES.new(key, AES.MODE_GCM)

    def encrypt(self, plaintext):
        nonce = self.cipher.nonce
        ciphertext, tag = self.cipher.encrypt_and_digest(plaintext)
        return nonce + tag + ciphertext

    def decrypt(self, ciphertext):
        nonce = ciphertext[:16]
        tag = ciphertext[16:32]
        ct = ciphertext[32:]
        try:
            decrypted = self.cipher.decrypt(ct)
            if self.cipher.verify(tag):
                return decrypted
            else:
                raise ValueError("Invalid tag")
        except ValueError as e:
            raise ValueError("Bad decryption") from e

